const GT_ST2_LOC={de:"de-CH",en:"en-GB",fr:"fr-CH",it:"it-CH",es:"es-ES",pt:"pt-PT"};
function gtSt2F(s,o){return String(s).replace(/\{(\w+):([^|}]*)\|([^}]*)\}/g,(m,k,a,b)=>o&&Number(o[k])===1?a:b).replace(/\{(\w+)\}/g,(m,k)=>o&&o[k]!=null?o[k]:m);}
function gtSt2RM(){try{return!!(window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches);}catch(e){return false;}}
function gtSt2Pct(r){const v=Number(r);return isFinite(v)?Math.round(v*100):0;}
function gtSt2Acc(theme,tk,game){if(!game)return tk.gold;if(theme==="noir")return noirAccent(game);return(typeof STATS_GAME_COLORS!=="undefined"&&STATS_GAME_COLORS[game])||tk.gold;}
function gtSt2Look(theme){const L=theme==="light",Nr=theme==="noir";return{L,Nr,track:L?"#E0D5BF":Nr?"#161616":"rgba(255,255,255,0.055)",segOn:L?"#FFFFFF":Nr?"#2A2A2A":"rgba(255,255,255,0.11)",segSh:L?"0 1px 2px rgba(20,24,32,0.12), 0 0 0 1px rgba(20,24,32,0.05)":"0 1px 2px rgba(0,0,0,0.35)",hover:L?"rgba(20,24,32,0.035)":"rgba(255,255,255,0.04)",line:L?"#CBBDA2":Nr?"#333333":"rgba(255,255,255,0.08)",barTrack:L?"#CBBDA2":Nr?"#3A3A3A":"#2E3446",ph:L?"#665E52":"rgba(242,244,248,0.55)",acc:L?"#6E4B0A":Nr?"#C1C1C1":"#C9A15C",onAcc:L?"#FFFFFF":Nr?"#111111":"#1A1408",bar:L?"#6E4B0A":Nr?"#EBEBEB":"#C9A15C",card2:L?"#E0D5BF":Nr?"#2C2C2C":"#262B3A"};}
function gtSt2Date(ts,lang,o){try{return new Date(ts).toLocaleDateString(GT_ST2_LOC[lang]||"de-CH",o||{day:"numeric",month:"short",year:"numeric"});}catch(e){return"";}}
function gtSt2NightDate(d,lang){const p=String(d||"").split("-").map(Number);if(p.length!==3||!p[0])return String(d||"");return gtSt2Date(new Date(p[0],p[1]-1,p[2]).getTime(),lang,{weekday:"short",day:"numeric",month:"short"});}
function gtSt2Label(id,t){try{if(typeof GT_STATS!=="undefined"&&GT_STATS.gameLabel)return GT_STATS.gameLabel(id,t);}catch(e){}return statsGameLabel(id,t);}
function GtSt2Num({v,suf}){const n=typeof v==="number"&&isFinite(v)?v:null;if(n==null)return <span>{v==null?"":String(v)}</span>;return <span className="gtSt2-num">{Math.round(n)+(suf||"")}</span>;}
function GtSt2Card({theme,tk,children,style,className,i,as,...rest}){return React.createElement(as||"section",{className:["",i!=null?"gtSt2-in":"",className||""].join(" ").trim()||undefined,style:{border:`1px solid ${tk.border}`,borderRadius:16,background:tk.card,padding:"14px 14px",minWidth:0,...(i!=null?{"--i":i}:{}),...style},...rest},children);}
function GtSt2H({tk,children,action,id,sub}){return <div style={{display:"flex",alignItems:"baseline",justifyContent:"space-between",gap:10,margin:"0 2px 10px"}}><div style={{minWidth:0}}><h2 id={id} style={{margin:0,fontSize:16,lineHeight:1.25,fontWeight:800,color:tk.ink,fontFamily:"'Inter', sans-serif",letterSpacing:"-0.01em"}}>{children}</h2>{sub&&<div style={{marginTop:2,fontSize:12.5,color:tk.muted,fontFamily:"'Inter', sans-serif",lineHeight:1.35}}>{sub}</div>}</div>{action||null}</div>;}
function GtSt2Link({tk,onClick,children,label,acc}){return <button type="button" onClick={onClick} aria-label={label} className="gtSt2-btn" style={{border:0,background:"transparent",color:acc||tk.gold,fontSize:".875rem",fontWeight:700,fontFamily:GT_ST2_FF,cursor:"pointer",padding:"6px 8px",minHeight:44,flexShrink:0}}>{children}</button>;}
function GtSt2Bar({value,color,track,i,h:hh}){const v=Math.max(0,Math.min(1,Number(value)||0));return <div aria-hidden style={{height:hh||6,borderRadius:99,background:track,overflow:"hidden",flex:1,minWidth:24}}><div className="gtSt2-grow" style={{"--i":i||0,width:Math.max(3,v*100)+"%",height:"100%",borderRadius:99,background:color}}/></div>;}
function GtSt2Avatar({name,acc,size,L}){const ch=String(name||"?").trim().charAt(0).toUpperCase()||"?";return <span aria-hidden style={{width:size||34,height:size||34,borderRadius:"50%",flexShrink:0,display:"inline-flex",alignItems:"center",justifyContent:"center",background:acc+(L?"22":"26"),color:L?shadeHex(acc,-0.35):acc,fontFamily:"'Baloo 2', sans-serif",fontWeight:800,fontSize:Math.round((size||34)*0.46),lineHeight:1,paddingTop:"0.08em"}}>{ch}</span>;}
function GtSt2Seg({value,onChange,options,lk,tk,label,tabs,idp}){const ref=useRef(null);const move=(e,i)=>{const k=e.key;let n=null;const c=options.length;if(k==="ArrowRight"||k==="ArrowDown")n=(i+1)%c;else if(k==="ArrowLeft"||k==="ArrowUp")n=(i-1+c)%c;else if(k==="Home")n=0;else if(k==="End")n=c-1;if(n==null)return;e.preventDefault();onChange(options[n].v);try{const b=ref.current&&ref.current.querySelectorAll("button")[n];if(b)b.focus();}catch(x){}};
return <div ref={ref} role={tabs?"tablist":"radiogroup"} aria-label={label} className="gtSt2-seg" style={{background:tk.card,border:`1px solid ${tk.border}`,"--st2-acc":lk.acc,"--st2-onacc":lk.onAcc,"--st2-tc":tk.ink,gridTemplateColumns:`repeat(${options.length},minmax(0,1fr))`}}>{options.map((o,i)=>{const on=o.v===value;const p=tabs?{role:"tab","aria-selected":on,id:idp+o.v,"aria-controls":idp+"panel"}:{role:"radio","aria-checked":on};return <button key={o.v} type="button" {...p} tabIndex={on?0:-1} onClick={()=>onChange(o.v)} onKeyDown={e=>move(e,i)} className={"gtSt2-segb"+(on?" is-on":"")}>{o.l}</button>;})}</div>;}
function GtSt2Select({label,value,display,options,onChange,tk,lk,active}){return <label className="gtSt2-sel gtSt2-btn" style={{position:"relative",display:"flex",alignItems:"center",gap:10,minHeight:48,padding:"0 12px",borderRadius:14,border:`1px solid ${active?lk.acc:tk.border}`,background:tk.card,cursor:"pointer",minWidth:0}}><span style={{fontSize:".8125rem",fontWeight:500,color:tk.muted,fontFamily:GT_ST2_FF,flexShrink:0}}>{label}</span><span style={{flex:1,minWidth:0,textAlign:"right",fontSize:".9375rem",fontWeight:600,color:tk.ink,fontFamily:GT_ST2_FF,whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{display}</span><svg width={14} height={14} viewBox="0 0 24 24" fill="none" aria-hidden style={{flexShrink:0}}><path d="M6 9l6 6 6-6" stroke={tk.muted} strokeWidth={2.2} strokeLinecap="round" strokeLinejoin="round"/></svg><select value={value==null?"":String(value)} onChange={e=>onChange(e.target.value===""?null:e.target.value)} aria-label={label}>{options.map(o=><option key={o.v} value={o.v}>{o.l}</option>)}</select></label>;}
function GtSt2Filters({t,tk,lk,range,setRange,game,setGame,groupId,setGroupId,groups,gameOpts,acc,onReset,lang}){const grp=groupId!=null?groups.find(g=>String(g.id)===String(groupId)):null;const active=range!=="all"||!!game||!!grp;const rl={all:t("st2RangeAll"),year:t("st2RangeYear"),"30d":t("st2Range30")};const parts=[];if(game)parts.push(gtSt2Label(game,t));if(grp)parts.push(grp.name);if(range!=="all")parts.push(rl[range]);
return <div className="gtSt2-filters" style={{marginBottom:14}}><GtSt2Seg value={range} onChange={setRange} lk={lk} tk={tk} label={t("st2Range")} options={[{v:"all",l:rl.all},{v:"year",l:rl.year},{v:"30d",l:rl["30d"]}]}/>
<GtSt2Select label={t("st2Game")} value={game} display={game?gtSt2Label(game,t):t("st2AllGames")} onChange={setGame} tk={tk} lk={lk} active={!!game} options={[{v:"",l:t("st2AllGames")}].concat(gameOpts.map(g=>({v:g.game,l:g.label})))}/>{groups.length>0&&<GtSt2Select label={t("st2Group")} value={grp?grp.id:null} display={grp?grp.name:t("st2AllGroups")} onChange={setGroupId} tk={tk} lk={lk} active={!!grp} options={[{v:"",l:t("st2AllGroups")}].concat(groups.map(g=>({v:String(g.id),l:g.name})))}/>}
{active&&<div role="status" style={{display:"flex",alignItems:"center",gap:8,padding:"0 2px",minHeight:44}}><span style={{flex:1,minWidth:0,fontSize:".8125rem",color:tk.muted,fontFamily:GT_ST2_FF,lineHeight:1.35}}>{t("st2Filtered")+": "}<b style={{color:tk.ink,fontWeight:700}}>{parts.join(" · ")}</b></span><GtSt2Link tk={tk} acc={lk.acc} onClick={onReset}>{t("st2Reset")}</GtSt2Link></div>}</div>;}
const GT_ST2_FF="'Inter', sans-serif";
const GT_ST2_LOGOS={skyjo:SkyjoLogo,flip7:Flip7Logo,"jass-differenzler":DifferenzlerLogo,schieber:SchieberLogo,yatzy:YatzyLogo,tutto:TuttoLogo,wizard:WizardLogo,minigolf:MinigolfLogo,freeplay:FreeplayLogo,darts:DartsLogo,cricket:CricketLogo,hiscore:HiScoreLogo,splitscore:SplitScoreLogo,shanghai:ShanghaiLogo,tabu:TabuLogo,headsup:HeadsUpLogo,fivesec:FiveSecLogo,impostor:ImpostorLogo,werwolf:WerewolfLogo,mafia:MafiaLogo,mostlikely:MostLikelyLogo};
function gtSt2Join(a,t){const and=t("st2And");return a.length<2?a.join(""):a.slice(0,-1).join(", ")+" "+and+" "+a[a.length-1];}
function GtSt2GameMark({game,theme,size}){const S=size||34;const Lg=GT_ST2_LOGOS[game];const c=(typeof STATS_GAME_COLORS!=="undefined"&&STATS_GAME_COLORS[game])||"#8E96A6";return Lg?<Lg color={c} theme={theme} size={S}/>:<span aria-hidden style={{width:S,height:S,display:"inline-flex",alignItems:"center",justifyContent:"center",flexShrink:0}}><span style={{width:12,height:12,borderRadius:"50%",background:c}}/></span>;}
function GtSt2Sec({tk,children,id}){return <h2 id={id} className="gtSt2-sec" style={{margin:"22px 2px 8px",fontSize:".8125rem",fontWeight:600,color:tk.muted,fontFamily:GT_ST2_FF,letterSpacing:".02em"}}>{children}</h2>;}
function GtSt2ListCard({tk,children,style}){return <div style={{background:tk.card,border:`1px solid ${tk.border}`,borderRadius:18,overflow:"hidden",minWidth:0,...style}}>{children}</div>;}
function GtSt2Chev({c}){return <svg width={16} height={16} viewBox="0 0 24 24" fill="none" aria-hidden style={{flexShrink:0}}><path d="M9 6l6 6-6 6" stroke={c} strokeWidth={2.2} strokeLinecap="round" strokeLinejoin="round"/></svg>;}
function GtSt2Kpis({s,t,tk,lk}){const tile=(label,val,sub,txt)=><div style={{background:tk.card,border:`1px solid ${tk.border}`,borderRadius:18,padding:12,minWidth:0}}><dt style={{fontSize:".75rem",color:tk.muted,fontFamily:GT_ST2_FF,lineHeight:1.3}}>{label}</dt><dd style={{margin:0,fontSize:txt?"1.1875rem":"1.5rem",fontWeight:700,letterSpacing:"-.02em",lineHeight:txt?1.45:1.2,color:tk.ink,fontFamily:GT_ST2_FF,overflowWrap:"anywhere",fontVariantNumeric:"tabular-nums"}}>{val}</dd>{sub&&<dd style={{margin:0,fontSize:".75rem",color:tk.muted,fontFamily:GT_ST2_FF,lineHeight:1.3}}>{sub}</dd>}</div>;const fav=s.matches>=2?s.favGame:null;
return <dl className="gtSt2-kpis" style={{margin:0}}>{tile(t("st2Matches"),s.matches||0)}{tile(t("st2Nights"),s.nights||0)}{tile(t("st2FavGame"),fav?fav.label:t("st2NoneYet"),fav?gtSt2F(t("st2TimesN"),{n:fav.count}):null,true)}</dl>;}
function GtSt2Lead({rows,t,tk}){if(!rows.length)return null;const top=rows.filter(r=>r.rank===1);const r0=top[0];if(!r0)return null;const head=top.length>3?gtSt2F(t("st2LeadTieMany"),{n:top.length}):top.length>1?gtSt2F(t("st2LeadTie"),{names:gtSt2Join(top.map(x=>x.name),t)}):gtSt2F(t("st2LeadOne"),{name:r0.name});return <p style={{margin:"14px 2px 0",fontSize:"1rem",lineHeight:1.4,color:tk.ink,fontFamily:GT_ST2_FF}}><b style={{fontWeight:700}}>{head}</b>{gtSt2F(t("st2LeadRest"),{w:r0.wins,n:r0.decided})}</p>;}
