const ok=typeof GT_STATS!=="undefined";
const year=useMemo(()=>{const y=new Date().getFullYear();try{const has=matches.some(m=>m&&m.status!=="open"&&new Date(m.ts).getFullYear()===y);return has?y:y-1;}catch(e){return y;}},[matches]);
