const calc=useMemo(()=>{if(!ok)return{err:new Error("GT_STATS fehlt")};try{if(typeof window!=="undefined"&&window.__gtStatsFail)throw new Error("Testschalter __gtStatsFail");const b=GT_STATS.build(matches,baseOpts);const mo=game?GT_STATS.build(matches,opts):b;const y=typeof GtYearReview==="function"?GT_STATS.yearReview(matches,year,{t,groups,tournaments:tours}):null;return{base:b,model:mo,yr:y,err:null};}catch(e){return{err:e};}},[matches,baseOpts,opts,year,lang,tours,retryN]);
